import { Component, inject, signal } from '@angular/core';
import { FormControl, ReactiveFormsModule, Validators } from '@angular/forms';
import { SessionService } from '../../core/session.service';

// Sign in by typing a name.
@Component({
  selector: 'app-signin',
  imports: [ReactiveFormsModule],
  template: `
    <form (ngSubmit)="submit()" aria-label="Sign in">
      <label for="signin-name">Name</label>
      <input id="signin-name" data-testid="signin-name" [formControl]="name" autocomplete="username" />
      <button type="submit" data-testid="signin-submit">Sign in</button>
      @if (error()) {
        <p role="alert" data-testid="signin-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class SignIn {
  private readonly session = inject(SessionService);
  protected readonly name = new FormControl('', { nonNullable: true, validators: Validators.required });
  protected readonly error = signal('');

  constructor() {
    this.name.valueChanges.subscribe(() => this.error.set(''));
  }

  protected submit(): void {
    this.error.set('');
    const name = this.name.value.trim();
    if (!name) {
      this.error.set('Enter a name.');
      return;
    }
    this.session.signIn(name).subscribe({ error: () => this.error.set('Could not sign in.') });
  }
}
